UPDATE region
   SET name = #{name}
 WHERE id = #{id}
   AND is_deleted = FALSE

UPDATE underpass
   SET region_id = #{toRegionId}
 WHERE region_id = #{fromRegionId}
   AND is_deleted = FALSE

UPDATE manager
   SET region_id = #{toRegionId}
 WHERE region_id = #{fromRegionId}
   AND status != 'WITHDRAWN'
